<script setup lang="ts">
import {ref} from 'vue';import {onShow,onLoad} from '@dcloudio/uni-app';import {labels} from '../../services/tasks';import type {SavedTask} from '../../services/tasks';const items=ref<SavedTask[]>([]),tab=ref('lists');onLoad(q=>tab.value=q?.tab==='me'?'me':'lists');onShow(()=>items.value=uni.getStorageSync('pinnedTools')||[]);
function open(task:SavedTask){uni.setStorageSync('pendingTool',task.config);uni.navigateTo({url:'/pages/tool/index?mode='+task.config.mode})}
function remove(id:string){uni.showModal({title:'删除这份名单？',content:'只删除当前设备固定的配置，云端活动不会受影响。',success:r=>{if(r.confirm){items.value=items.value.filter(x=>x.id!==id);uni.setStorageSync('pinnedTools',items.value)}}})}
function rename(task:SavedTask){uni.showModal({title:'名单名称',editable:true,placeholderText:task.config.name||labels[task.config.mode],success:r=>{if(r.confirm&&r.content?.trim()){task.config.name=r.content.trim();uni.setStorageSync('pinnedTools',items.value)}}})}
function back(){uni.navigateBack()}
</script><template><view class="page"><view class="title">{{tab==='me'?'我的':'我的名单'}}</view><view v-if="tab==='me'" class="card"><view>随机一下</view><view class="muted">已固定 {{items.length}} 份配置 · 普通工具保存在本机</view><view class="muted">活动抽奖使用微信云开发，当前仍为开发预览版。</view><button @click="tab='lists'">查看我的名单</button></view><template v-else><view class="muted">长期复用的班级、团队与选项池</view><view v-if="!items.length" class="card">还没有固定名单。完成一次随机后，可选择“固定这份配置”。</view><view v-for="task in items" :key="task.id" class="card"><view class="title">{{task.config.name||labels[task.config.mode]}}</view><view class="muted">{{labels[task.config.mode]}} · {{task.config.items.length}} 项</view><button @click="open(task)">使用</button><view class="actions"><text @click="rename(task)">改名</text><text @click="remove(task.id)">删除</text></view></view></template><button @click="back">返回</button></view></template><style scoped>.title{font-size:23px;font-weight:800}.actions{display:flex;gap:28px;color:#6657e8;font-size:14px}</style>
